import { BlockNoteSchema } from "../blocks/BlockNoteSchema.js";
import { BlockFromConfigNoChildren, BlockSchema, InlineContentFromConfig, InlineContentSchema, StyleSchema, Styles } from "../schema/index.js";
import type { Exporter } from "./Exporter.js";
/**
 * Defines a mapping from all block types with a schema to a result type `R`.
 * Each block type maps to either:
 * - a function that renders the block itself. The exporter places the
 *   block's children after it, nested as the format does it; or
 * - `{ withChildren }`, a function that renders the block *and* its
 *   children, which it receives already rendered as its last argument. For
 *   blocks whose children are part of them, like a column or a callout's
 *   body. Layout blocks must use it.
 */
export type BlockMapping<B extends BlockSchema, I extends InlineContentSchema, S extends StyleSchema, RB, RI> = {
    [K in keyof B]: BlockMappingFunction<B[K], I, S, RB, RI> | {
        withChildren: BlockMappingWithChildrenFunction<B[K], I, S, RB, RI>;
    };
};
export type BlockMappingFunction<C extends BlockSchema[string], I extends InlineContentSchema, S extends StyleSchema, RB, RI> = (block: BlockFromConfigNoChildren<C, I, S>, exporter: Exporter<any, any, any, RB, RI, any, any>, nestingLevel: number, numberedListIndex?: number) => RB | Promise<RB>;
/** A `{ withChildren }` mapping: it also receives the block's rendered children. */
export type BlockMappingWithChildrenFunction<C extends BlockSchema[string], I extends InlineContentSchema, S extends StyleSchema, RB, RI> = (block: BlockFromConfigNoChildren<C, I, S>, exporter: Exporter<any, any, any, RB, RI, any, any>, nestingLevel: number, numberedListIndex: number | undefined, children: Array<Awaited<RB>>) => RB | Promise<RB>;
/**
 * Defines a mapping from all inline content types with a schema to a result type R.
 */
export type InlineContentMapping<I extends InlineContentSchema, S extends StyleSchema, RI, TS> = {
    [K in keyof I]: (inlineContent: InlineContentFromConfig<I[K], S>, exporter: Exporter<any, any, any, any, RI, any, TS>) => RI;
};
/**
 * Defines a mapping from all style types with a schema to a result type R.
 */
export type StyleMapping<S extends StyleSchema, RS> = {
    [K in keyof S]: (style: Styles<S>[K], exporter: Exporter<any, any, any, any, any, RS, any>) => RS;
};
/**
 * The mapping factory is a utility function to easily create mappings for
 * a BlockNoteSchema. Using the factory makes it easier to get typescript code completion etc.
 */
export declare function mappingFactory<B extends BlockSchema, I extends InlineContentSchema, S extends StyleSchema>(_schema: BlockNoteSchema<B, I, S>): {
    createBlockMapping: <R, RI>(mapping: BlockMapping<B, I, S, R, RI>) => BlockMapping<B, I, S, R, RI>;
    createInlineContentMapping: <R, RS>(mapping: InlineContentMapping<I, S, R, RS>) => InlineContentMapping<I, S, R, RS>;
    createStyleMapping: <R>(mapping: StyleMapping<S, R>) => StyleMapping<S, R>;
};
